"""Static same-origin fixture dashboard. No scanner/API/ground-truth access."""

from pathlib import Path

HTML = r"""<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ZELNX · Synthetic Banking Estate</title>
<style>
:root{color-scheme:dark;font:14px system-ui;background:#0b1020;color:#e7edf8}*{box-sizing:border-box}body{margin:0;display:grid;grid-template-columns:230px 1fr;min-height:100vh}aside{background:#10172b;padding:30px 24px;border-right:1px solid #24304a}h1{font-size:24px;letter-spacing:-.5px;margin:0}aside strong{color:#7df0ce;font-size:22px}aside p{color:#8e9bb7;line-height:1.7}nav{margin-top:38px;display:grid;gap:20px}nav a{color:#dce6fa;text-decoration:none}.tag{display:inline-block;border:1px solid #567661;color:#a6f2ba;border-radius:5px;padding:5px 9px;font-size:11px;letter-spacing:1px}.warning{background:#30291a;color:#f4cf84;padding:15px 20px;border:1px solid #66522e;border-radius:9px;line-height:1.6}main{padding:35px;max-width:1600px;width:100%}header{display:flex;justify-content:space-between;align-items:center;margin-bottom:25px}.muted{color:#9ba8c3}.cards{display:grid;grid-template-columns:repeat(5,1fr);gap:13px;margin:24px 0}.card{background:#141e34;border:1px solid #293650;border-radius:10px;padding:18px}.card b{display:block;font-size:27px;margin-top:10px;color:#79e9d4}.card span{color:#adbbd2;font-size:12px}.panel{background:#111b30;border:1px solid #293650;border-radius:10px;padding:23px;margin:20px 0}h2{font-size:17px;margin-top:0}.filters{display:grid;grid-template-columns:repeat(3,1fr);gap:13px}label{font-size:12px;color:#adbbd2}select{display:block;margin-top:7px;width:100%;padding:12px;background:#0a1429;color:#e7edf8;border:1px solid #354767;border-radius:6px}.columns{display:grid;grid-template-columns:1fr 1fr;gap:18px}pre{font-size:12px;white-space:pre-wrap;overflow-wrap:anywhere;max-height:460px;overflow:auto;line-height:1.7;color:#b4c8e3}table{width:100%;border-collapse:collapse}td,th{padding:11px;text-align:left;border-bottom:1px solid #263550;font-size:12px}.status{color:#f1cb72}footer{color:#92a0b8;line-height:1.8;font-size:12px}@media(max-width:950px){body{grid-template-columns:1fr}aside{display:none}.cards{grid-template-columns:repeat(3,1fr)}.columns,.filters{grid-template-columns:1fr}main{padding:20px}}
</style></head><body><aside><strong>ZELNX</strong><p>CRYPTOSCAN LAB<br>Banking estate simulator</p><span class="tag">SYNTHETIC ONLY</span><nav><a href="#overview">◈ &nbsp; Estate overview</a><a href="#explore">▦ &nbsp; Asset explorer</a><a href="#bom">◇ &nbsp; Six BOM coverage</a><a href="#evidence">≋ &nbsp; Evidence & conflicts</a></nav><p style="margin-top:80px">Offline fixtures.<br>No customer connectivity.<br>No production secrets.</p></aside><main><header><div><p class="muted">ENGINEERING / CONTROLLED TEST ESTATE</p><h1>Cryptography across the banking estate</h1></div><span class="tag">LAB · GENERATED INVENTORY</span></header><div class="warning">These are <b>generated fixture counts</b>, not CryptoScan discoveries or proven runtime usage. PQC, cloud, HSM and legacy metadata are simulations unless a separate live-test receipt says otherwise.</div><section id="overview" class="cards"></section><section class="panel" id="explore"><h2>Explore the estate</h2><p class="muted">Bank → data center → network zone → system → application → component → evidence</p><div class="filters"><label>Institution<select id="bank"></select></label><label>Data center<select id="dc"></select></label><label>Network zone<select id="zone"></select></label><label>System<select id="system"></select></label><label>Application<select id="app"></select></label><label>Component<select id="component"></select></label></div></section><section class="panel" id="loadbalancers"><h2>Load balancer / ADC crypto paths</h2><p class="muted">Configured fixtures only · supported ≠ negotiated · each TLS hop is a separate asset</p><div class="filters"><label>Load balancer<select id="lb"></select></label><label>Scenario / listener<select id="lbcase"></select></label></div><div class="columns"><div><h3>Topology and hop ownership</h3><pre id="lbpath"></pre></div><div><h3>Independent crypto hops and evidence</h3><pre id="lbhops"></pre></div></div></section><section class="columns"><div class="panel" id="bom"><h2>Six BOM projections</h2><table><thead><tr><th>Projection</th><th>Scope</th></tr></thead><tbody><tr><td>NBOM</td><td>Segmented paths & endpoints</td></tr><tr><td>CBOM</td><td>Declared crypto; not proof of execution</td></tr><tr><td>SBOM</td><td>CycloneDX / SPDX package evidence</td></tr><tr><td>TechBOM</td><td>Providers, versions & dependencies</td></tr><tr><td>HBOM</td><td>Synthetic hardware & firmware</td></tr><tr><td>VBOM</td><td>Fictional products & declarations</td></tr></tbody></table><h2 style="margin-top:25px">Selected asset</h2><pre id="detail"></pre></div><div class="panel" id="evidence"><h2>Evidence & provenance</h2><p class="status">UNKNOWN ≠ SAFE · INSTALLED ≠ USED</p><pre id="facts"></pre><h2>Related conflict / drift fixtures</h2><pre id="conflicts"></pre></div></section><footer>Reserved documentation addresses and .invalid names are labels, not scan targets. No external scripts, fonts, trackers or cloud connections. Ground truth and expected results are not served by this dashboard.<br><span id="state"></span></footer></main><script>
'use strict';let catalog, data={};const $=id=>document.getElementById(id);const fields=['bank','dc','zone','system','app','component'];let generation=0;
async function json(path){let r=await fetch(path,{cache:'no-store'});if(!r.ok)throw Error('Read failed: '+path);return r.json()}
async function lines(path){let r=await fetch(path,{cache:'no-store'});if(!r.ok)throw Error('Read failed: '+path);return (await r.text()).split('\n').filter(x=>x.trim()).map(x=>JSON.parse(x))}
function opts(id,items,all){let s=$(id);s.replaceChildren();if(all){let o=document.createElement('option');o.value='';o.textContent=all;s.append(o)}for(let [value,text] of items){let o=document.createElement('option');o.value=value;o.textContent=text;s.append(o)}}
function lbcases(){let c=data.lbcases.filter(x=>x.lb_id===$('lb').value);opts('lbcase',c.map(x=>[x.case_id,x.scenario]));lbdetails()}
function lbdetails(){let c=data.lbcases.find(x=>x.case_id===$('lbcase').value);$('lbpath').textContent=JSON.stringify({node:data.lbInventory.nodes.find(x=>x.lb_id===$('lb').value),scenario:c},null,2);$('lbhops').textContent=JSON.stringify(data.lbhops.filter(x=>c?.hop_ids.includes(x.hop_id)),null,2)}
function show(){let sys=data.systems.filter(s=>(!$('dc').value||s.data_center===$('dc').value)&&(!$('zone').value||s.zone===$('zone').value));opts('system',sys.map(s=>[s.system_id,s.system_id]));apps()}
function apps(){let a=data.applications.filter(x=>x.system_id===$('system').value);opts('app',a.map(x=>[x.app_id,x.app_id]));components()}
function components(){let a=data.applications.find(x=>x.app_id===$('app').value);let c=data.techbom.filter(x=>x.app_id===a?.app_id);opts('component',c.map(x=>[x.component_id,x.name+' · '+x.declared_version]));details()}
function details(){let a=data.applications.find(x=>x.app_id===$('app').value);let c=data.techbom.find(x=>x.app_id===a?.app_id&&x.component_id===$('component').value);$('detail').textContent=JSON.stringify({application:a,component:c},null,2);$('facts').textContent=JSON.stringify(data.fixtures.filter(f=>f.application===a?.app_id),null,2);$('conflicts').textContent=JSON.stringify(data.scenarios.filter(s=>s.subject===a?.app_id||s.other_subject===a?.app_id),null,2)}
async function bank(){let g=++generation;let b=$('bank').value;$('state').textContent='Loading '+b+'…';let names=['systems','applications','techbom','fixtures','scenarios'];let values=await Promise.all(names.map(n=>lines(n+'/'+b+'.jsonl')));let lbvalues=await Promise.all([json('load_balancers/'+b+'/inventory.json'),lines('load_balancers/'+b+'/cases.jsonl'),lines('load_balancers/'+b+'/hops.jsonl')]);if(g!==generation)return;data=Object.fromEntries(names.map((n,i)=>[n,values[i]]));data.lbInventory=lbvalues[0];data.lbcases=lbvalues[1];data.lbhops=lbvalues[2];opts('lb',data.lbInventory.nodes.map(x=>[x.lb_id,x.role+' · '+x.lb_id]));lbcases();opts('dc',[...new Set(data.systems.map(s=>s.data_center))].map(x=>[x,x]),'All data centers');opts('zone',[...new Set(data.systems.map(s=>s.zone))].map(x=>[x,x]),'All zones');show();$('state').textContent='Loaded '+b+' · synthetic fixture inventory'}
(async()=>{catalog=await json('catalog.json');let labels={load_balancers:'Load balancers / ADC',lb_scenarios:'LB scenarios',lb_crypto_hops:'Declared LB crypto hops',banks:'Banks',systems:'Systems',applications:'Applications',services:'Services / endpoints',components:'Component instances',certificates:'Certificates',hsm:'HSM simulations',kms_keys:'KMS key metadata',vendors:'Vendor product records',lb_sbom_documents:'LB SBOM documents',sbom:'Base estate SBOM documents',cbom:'Base estate CBOM declarations',unknown:'Unknown scenarios',weak:'Weak fixture scenarios',deprecated:'Deprecated scenarios',pqc:'Banks with PQC fixtures',drift:'Drift scenarios',conflicts:'Conflicting declarations'};for(let [k,l] of Object.entries(labels)){let card=document.createElement('div');card.className='card';let s=document.createElement('span');s.textContent=l;let b=document.createElement('b');b.textContent=(catalog.counts[k]||0).toLocaleString();card.append(s,b);$('overview').append(card)}opts('bank',catalog.banks.map(b=>[b.bank_id,b.name]));$('bank').onchange=()=>bank().catch(error);$('dc').onchange=show;$('zone').onchange=show;$('system').onchange=apps;$('app').onchange=components;$('component').onchange=details;$('lb').onchange=lbcases;$('lbcase').onchange=lbdetails;await bank()})().catch(error);
function error(e){$('state').textContent='FAILED: '+e.message+' — use the local read-only dashboard server; do not open file:// directly.'}
</script></body></html>"""


def render(public):
    (Path(public) / "index.html").write_text(HTML)
